System.Collections.IEnumerator Check(){
 var rig=UnityEngine.Object.FindObjectOfType<Character.Control.PaddleCharacterVisual>();
 foreach(var a in rig.GetComponentsInChildren<Character.Control.ArmsSimulation>())a.enabled=false;
 foreach(var t in UnityEngine.Object.FindObjectsOfType<Character.Control.TargetMovement>())t.enabled=false;
 foreach(var rb in rig.GetComponentsInChildren<UnityEngine.Rigidbody2D>())rb.simulated=false;
 float maxStep=0,maxError=0,minGap=100;float last=rig.leftUpper.transform.eulerAngles.z;
 for(int i=0;i<100;i++){
  rig.tool.rotation=UnityEngine.Quaternion.Euler(0,0,35);
  var shoulder=rig.body.position+rig.body.up*.66f-rig.body.right*.245f;
  var targetHand=shoulder+new UnityEngine.Vector3(UnityEngine.Mathf.Sin(i*.13f)*.12f,0,0);
  var targetTip=targetHand+rig.tool.right*1.1f;
  rig.tool.position+=targetTip-rig.tip.position;
  yield return null;
  float angle=rig.leftUpper.transform.eulerAngles.z;
  if(i>0)maxStep=UnityEngine.Mathf.Max(maxStep,UnityEngine.Mathf.Abs(UnityEngine.Mathf.DeltaAngle(last,angle)));
  last=angle;maxError=UnityEngine.Mathf.Max(maxError,rig.HandError);minGap=UnityEngine.Mathf.Min(minGap,UnityEngine.Vector3.Distance(rig.LeftHand,rig.RightHand));
 }
 string log="Repeated shoulder singularity crossings: max one-frame upper-arm rotation="+maxStep+" (cap27deg); max wrist error="+maxError+" min grip separation="+minGap;
 System.IO.File.WriteAllText("scripts/player-grip-20261111/singularity.txt",log);UnityEngine.Debug.Log(log);
 if(maxStep>27.1f||maxError>.001f||minGap<.59f)throw new System.Exception("Discontinuous arm regression");
}
return Check();
